58	/**
59	 * Shallow-clone a test case so the caller can swap in resolved ApiProvider
60	 * instances on `options.provider` / `assert[].provider` without leaking those
61	 * mutations back to the input. The input may alias the unified config written
62	 * to the Eval record, and a live SDK client (e.g. Bedrock's BedrockRuntime,
63	 * Anthropic's client) holds circular references that break drizzle's JSON
64	 * serialization on `evalRecord.save()`. Fixes #8687.
65	 *
66	 * Detaches only `options` and `assert[]`. Other reference fields (`provider`,
67	 * `vars`, `metadata`, `providerOutput`) remain aliased — callers must reassign
68	 * those by reference rather than mutating in place. `assert-set` children are
69	 * not deep-cloned because the resolve loop skips `assert-set`; if that ever
70	 * changes, extend this helper.
71	 */
72	function cloneTestForResolve<T extends Pick<TestCase, 'options' | 'assert'>>(test: T): T {
73	  const cloned: T = { ...test };
74	  if (test.options) {
75	    cloned.options = { ...test.options };
76	  }
77	  if (test.assert) {
78	    cloned.assert = test.assert.map((assertion) => ({ ...assertion }));
79	  }
80	  return cloned;
81	}
