83	function toSerializableProviderRef(provider: unknown): unknown {
84	  if (isApiProvider(provider)) {
85	    return sanitizeProvider(provider);
86	  }
87	  if (Array.isArray(provider)) {
88	    return provider.map(toSerializableProviderRef);
89	  }
90	  return provider;
91	}
