97	function withSerializableProvider<T extends Record<string, unknown>>(record: T): T {
98	  if (!isApiProvider(record.provider)) {
99	    return record;
100	  }
101	  return {
102	    ...record,
103	    provider: sanitizeProvider(record.provider),
104	  };
105	}
