107	/**
108	 * Function-valued transforms are first-class at runtime but are silently dropped
109	 * by `JSON.stringify`. Persisted eval configs (drizzle-stored) must never retain
110	 * a function reference, so replace every `transform`-like field with a
111	 * `[inline function]: name` marker. Non-function values pass through unchanged.
112	 *
113	 * `droppedRef.value` is flipped to `true` the first time a function is replaced
114	 * so the caller can emit a single warning instead of logging per field.
115	 */
116	function replaceFunctionTransforms<T extends Record<string, unknown>>(
117	  record: T,
118	  droppedRef: { value: boolean },
119	): T {
120	  let result: T | undefined;
121	  for (const key of TRANSFORM_KEYS) {
122	    const value = record[key];
123	    if (!isTransformFunction(value)) {
124	      continue;
125	    }
126	    if (!result) {
127	      result = { ...record };
128	    }
129	    (result as Record<string, unknown>)[key] = value.name
130	      ? `${INLINE_FUNCTION_LABEL}: ${value.name}`
131	      : INLINE_FUNCTION_LABEL;
132	    droppedRef.value = true;
133	  }
134	  return result ?? record;
135	}
