import { getDefaultProviders } from './providers/defaults';
import { MAX_SUGGESTIONS_COUNT } from './types/index';
import {
  accumulateTokenUsage,
  createEmptyTokenUsage,
  normalizeTokenUsage,
} from './util/tokenUsageUtils';

import type { TokenUsage } from './types/index';

interface GeneratePromptsOutput {
  prompts?: string[];
  error?: string;
  tokensUsed: TokenUsage;
}

/**
 * Generate `num` alternative variants for the given prompt.
 *
 * The provider is called once per requested variant and token usage is
 * accumulated across all calls. If at least one call succeeds, the successful
 * outputs are returned (partial success) and no error is set. If every call
 * fails, `prompts` is undefined and `error` is a semicolon-separated summary of
 * each variant's failure.
 */
export async function generatePrompts(
  prompt: string,
  num: number,
): Promise<GeneratePromptsOutput> {
  if (!Number.isInteger(num) || num < 1 || num > MAX_SUGGESTIONS_COUNT) {
    return {
      error: `num must be an integer between 1 and ${MAX_SUGGESTIONS_COUNT}`,
      tokensUsed: createEmptyTokenUsage(),
    };
  }

  const provider = (await getDefaultProviders()).suggestionsProvider;
  const tokensUsed = createEmptyTokenUsage();
  const prompts: string[] = [];
  const errors: string[] = [];

  for (let i = 0; i < num; i++) {
    try {
      const resp = await provider.callApi(
        JSON.stringify([
          SUGGEST_PROMPTS_SYSTEM_MESSAGE,
          {
            role: 'user',
            content: 'Generate a variant for the following prompt:',
          },
          {
            role: 'user',
            content: prompt,
          },
        ]),
      );
      accumulateTokenUsage(tokensUsed, normalizeTokenUsage(resp.tokenUsage));
      if (resp.error || !resp.output) {
        errors.push(resp.error || 'Unknown error');
        continue;
      }
      prompts.push(String(resp.output));
    } catch (err) {
      errors.push(err instanceof Error ? err.message : String(err));
    }
  }

  if (prompts.length === 0) {
    return {
      error: errors.map((error, index) => `Variant ${index + 1}: ${error}`).join('; '),
      tokensUsed,
    };
  }

  return {
    prompts,
    tokensUsed,
  };
}
